// GraphServiceHandler is an implementation of the goap.graph.v1.GraphService service.
type GraphServiceHandler interface {
	// Domain axis
	GetNode(context.Context, *connect.Request[v1.GetNodeRequest]) (*connect.Response[v1.GetNodeResponse], error)
	ListBaselines(context.Context, *connect.Request[v1.ListBaselinesRequest]) (*connect.Response[v1.ListBaselinesResponse], error)
	// Tags (ADR 0056) name the state an applied change leaves; not unique, a name may label several changes.
	TagChange(context.Context, *connect.Request[v1.TagChangeRequest]) (*connect.Response[v1.TagChangeResponse], error)
	ListTags(context.Context, *connect.Request[v1.ListTagsRequest]) (*connect.Response[v1.ListTagsResponse], error)
	DeleteTag(context.Context, *connect.Request[v1.DeleteTagRequest]) (*connect.Response[v1.DeleteTagResponse], error)
	GetBaselineGraph(context.Context, *connect.Request[v1.GetBaselineGraphRequest]) (*connect.Response[v1.GetBaselineGraphResponse], error)
	// Browsing a large baseline: a page of its nodes (by type, filtered) and the neighbourhood of one node.
	ListBaselineNodes(context.Context, *connect.Request[v1.ListBaselineNodesRequest]) (*connect.Response[v1.ListBaselineNodesResponse], error)
	ListBaselineLinks(context.Context, *connect.Request[v1.ListBaselineLinksRequest]) (*connect.Response[v1.ListBaselineLinksResponse], error)
	GetNodeNeighbourhood(context.Context, *connect.Request[v1.GetNodeNeighbourhoodRequest]) (*connect.Response[v1.GetNodeNeighbourhoodResponse], error)
	// The namespaces holding at least one node.
	ListNamespaces(context.Context, *connect.Request[v1.ListNamespacesRequest]) (*connect.Response[v1.ListNamespacesResponse], error)
	// The structures of the graph (ADR 0054): the organisation and the projects, with the node types belonging to each.
	GetStructures(context.Context, *connect.Request[v1.GetStructuresRequest]) (*connect.Response[v1.GetStructuresResponse], error)
	// Whether a node type is written by platform administrators only (`adminOnly:` on the node type, ADR 0068).
	IsAdminOnlyType(context.Context, *connect.Request[v1.IsAdminOnlyTypeRequest]) (*connect.Response[v1.IsAdminOnlyTypeResponse], error)
	// The impact log of a change (ADR 0029): every operation on its change impacts, with its caller.
	ListChangeEvents(context.Context, *connect.Request[v1.ListChangeEventsRequest]) (*connect.Response[v1.ListChangeEventsResponse], error)
	// The log of a change (ADR 0030): its facts, journal records and impact events in one order, filtered on columns.
	ListChangeLog(context.Context, *connect.Request[v1.ListChangeLogRequest]) (*connect.Response[v1.ListChangeLogResponse], error)
	// The whole log of a change as W3C PROV-O provenance, in JSON-LD (ADR 0057).
	ExportChangeProvenance(context.Context, *connect.Request[v1.ExportChangeProvenanceRequest]) (*connect.Response[v1.ExportChangeProvenanceResponse], error)
	// Change axis
	CreateChange(context.Context, *connect.Request[v1.CreateChangeRequest]) (*connect.Response[v1.CreateChangeResponse], error)
	GetChange(context.Context, *connect.Request[v1.GetChangeRequest]) (*connect.Response[v1.GetChangeResponse], error)
	ListChanges(context.Context, *connect.Request[v1.ListChangesRequest]) (*connect.Response[v1.ListChangesResponse], error)
	// The versions a change starts from (the pre version of its change impacts), and the
	// changes acting on a node (ADR 0024).
	GetChangeImpacts(context.Context, *connect.Request[v1.GetChangeImpactsRequest]) (*connect.Response[v1.GetChangeImpactsResponse], error)
	ListNodeChanges(context.Context, *connect.Request[v1.ListNodeChangesRequest]) (*connect.Response[v1.ListNodeChangesResponse], error)
	UpdateChange(context.Context, *connect.Request[v1.UpdateChangeRequest]) (*connect.Response[v1.UpdateChangeResponse], error)
	AddItems(context.Context, *connect.Request[v1.AddItemsRequest]) (*connect.Response[v1.AddItemsResponse], error)
	// Change impacts (ADR 0024): declare the nodes a change acts on, write the version each produces on the
	// change branch, and accept or reject them (a comment is mandatory).
	ProposeImpact(context.Context, *connect.Request[v1.ProposeImpactRequest]) (*connect.Response[v1.ProposeImpactResponse], error)
	// Node edits (ADR 0076): every write names a change. ImpactNodeCreate and ImpactNodeCheckout write the working version of the
	// node in the change, checked out; ImpactNodeUpdate and the link operations edit it in place; an accepted review
	// authorizes ImpactNodeCheckin, which freezes it; ImpactNodeTransition moves a checked-in node along its lifecycle (a version of
	// its own); ImpactNodeCancel drops the working version (a creation cancelled before its first check-in removes the node).
	ImpactNodeCreate(context.Context, *connect.Request[v1.ImpactNodeCreateRequest]) (*connect.Response[v1.ImpactNodeCreateResponse], error)
	ImpactNodeCheckout(context.Context, *connect.Request[v1.ImpactNodeCheckoutRequest]) (*connect.Response[v1.ImpactNodeCheckoutResponse], error)
	ImpactNodeUpdate(context.Context, *connect.Request[v1.ImpactNodeUpdateRequest]) (*connect.Response[v1.ImpactNodeUpdateResponse], error)
	ImpactLinkCreate(context.Context, *connect.Request[v1.ImpactLinkCreateRequest]) (*connect.Response[v1.ImpactLinkCreateResponse], error)
	ImpactLinkUpdate(context.Context, *connect.Request[v1.ImpactLinkUpdateRequest]) (*connect.Response[v1.ImpactLinkUpdateResponse], error)
	ImpactLinkDelete(context.Context, *connect.Request[v1.ImpactLinkDeleteRequest]) (*connect.Response[v1.ImpactLinkDeleteResponse], error)
	ImpactNodeCheckin(context.Context, *connect.Request[v1.ImpactNodeCheckinRequest]) (*connect.Response[v1.ImpactNodeCheckinResponse], error)
	ImpactNodeTransition(context.Context, *connect.Request[v1.ImpactNodeTransitionRequest]) (*connect.Response[v1.ImpactNodeTransitionResponse], error)
	ImpactNodeCancel(context.Context, *connect.Request[v1.ImpactNodeCancelRequest]) (*connect.Response[v1.ImpactNodeCancelResponse], error)
	// Merge nodes into a new one, split one into new ones, seen from the parent side (ADR 0077): the parents lose the
	// links to the sources and gain the links to the successors, the sources stay untouched with the impact of their
	// parent as via.
	ImpactNodeMerge(context.Context, *connect.Request[v1.ImpactNodeMergeRequest]) (*connect.Response[v1.ImpactNodeRestructureResponse], error)
	ImpactNodeSplit(context.Context, *connect.Request[v1.ImpactNodeSplitRequest]) (*connect.Response[v1.ImpactNodeRestructureResponse], error)
	// Take a change impact out of the change, explicitly: its working version is dropped (refused once a version of it
	// is checked in: reject it instead).
	WithdrawImpact(context.Context, *connect.Request[v1.WithdrawImpactRequest]) (*connect.Response[v1.WithdrawImpactResponse], error)
	ImpactNodeReview(context.Context, *connect.Request[v1.ImpactNodeReviewRequest]) (*connect.Response[v1.ImpactNodeReviewResponse], error)
	ReopenChangeImpacts(context.Context, *connect.Request[v1.ReopenChangeImpactsRequest]) (*connect.Response[v1.ReopenChangeImpactsResponse], error)
	// Producers: a whole change of node edits (change impacts, versions, reviews, apply) in one call.
	CommitEdits(context.Context, *connect.Request[v1.CommitEditsRequest]) (*connect.Response[v1.CommitEditsResponse], error)
	GetBlackboard(context.Context, *connect.Request[v1.GetBlackboardRequest]) (*connect.Response[v1.GetBlackboardResponse], error)
	ApplyChange(context.Context, *connect.Request[v1.ApplyChangeRequest]) (*connect.Response[v1.ApplyChangeResponse], error)
	// Move the state of a change along a transition of its lifecycle (ADR 0058): its guard (a decided decision point,
	// the expected world state) must hold, and it is journaled.
	TransitionChange(context.Context, *connect.Request[v1.TransitionChangeRequest]) (*connect.Response[v1.TransitionChangeResponse], error)
	// Remove a change that landed nothing, with its log (ADR 0037). Refused once anything of it is applied or used.
	DeleteChange(context.Context, *connect.Request[v1.DeleteChangeRequest]) (*connect.Response[v1.DeleteChangeResponse], error)
	// Version branches (ADR 0009)
	CreateBranch(context.Context, *connect.Request[v1.CreateBranchRequest]) (*connect.Response[v1.CreateBranchResponse], error)
	ListBranches(context.Context, *connect.Request[v1.ListBranchesRequest]) (*connect.Response[v1.ListBranchesResponse], error)
	GetBranch(context.Context, *connect.Request[v1.GetBranchRequest]) (*connect.Response[v1.GetBranchResponse], error)
	SetBranchStatus(context.Context, *connect.Request[v1.SetBranchStatusRequest]) (*connect.Response[v1.SetBranchStatusResponse], error)
	SetBranchDescription(context.Context, *connect.Request[v1.SetBranchDescriptionRequest]) (*connect.Response[v1.SetBranchDescriptionResponse], error)
	ListNodeVersions(context.Context, *connect.Request[v1.ListNodeVersionsRequest]) (*connect.Response[v1.ListNodeVersionsResponse], error)
	// The first versions of the nodes that derive from a node: the successors of the merges and splits that replaced it
	// (ADR 0077). Node.origins answers the other way.
	DerivedNodes(context.Context, *connect.Request[v1.DerivedNodesRequest]) (*connect.Response[v1.DerivedNodesResponse], error)
	PlanMerge(context.Context, *connect.Request[v1.PlanMergeRequest]) (*connect.Response[v1.PlanMergeResponse], error)
	MergeBranch(context.Context, *connect.Request[v1.MergeBranchRequest]) (*connect.Response[v1.MergeBranchResponse], error)
	// What going from a baseline to another changes, node by node (same namespace).
	DiffBaselines(context.Context, *connect.Request[v1.DiffBaselinesRequest]) (*connect.Response[v1.DiffBaselinesResponse], error)
	// Integrates a committed change that waits for a resolution: merges its branch into the branch it forked from (ADR 0056).
	MergeChange(context.Context, *connect.Request[v1.MergeChangeRequest]) (*connect.Response[v1.MergeChangeResponse], error)
	// Nodes the change shares with other open changes (a merge will be needed).
	GetSharedNodes(context.Context, *connect.Request[v1.GetSharedNodesRequest]) (*connect.Response[v1.GetSharedNodesResponse], error)
	// Splits a change along organisational boundaries: one sub-change per unit owning impacted nodes.
	SplitChange(context.Context, *connect.Request[v1.SplitChangeRequest]) (*connect.Response[v1.SplitChangeResponse], error)
	ListSubChanges(context.Context, *connect.Request[v1.ListSubChangesRequest]) (*connect.Response[v1.ListSubChangesResponse], error)
	// Action flow branches: a relaunched step forks the flow, a human adopts or discards the branch.
	OpenFlow(context.Context, *connect.Request[v1.OpenFlowRequest]) (*connect.Response[v1.OpenFlowResponse], error)
	AdoptFlow(context.Context, *connect.Request[v1.AdoptFlowRequest]) (*connect.Response[v1.AdoptFlowResponse], error)
	DiscardFlow(context.Context, *connect.Request[v1.DiscardFlowRequest]) (*connect.Response[v1.DiscardFlowResponse], error)
	ListFlows(context.Context, *connect.Request[v1.ListFlowsRequest]) (*connect.Response[v1.ListFlowsResponse], error)
	// Applies the proposals of a flow on a graph branch of its own (a preview, merged when the flow is adopted).
	// Consistency check of the blackboard as a process on a flow sees it.
	ValidateBoard(context.Context, *connect.Request[v1.ValidateBoardRequest]) (*connect.Response[v1.ValidateBoardResponse], error)
	// Options of a change (ADR 0009 §3, ADR 0032 §6): hypotheses explored on flows of their own; the active one is
	// where every call that names no flow goes ("main" names the main flow).
	OpenOption(context.Context, *connect.Request[v1.OpenOptionRequest]) (*connect.Response[v1.OpenOptionResponse], error)
	ActivateOption(context.Context, *connect.Request[v1.ActivateOptionRequest]) (*connect.Response[v1.ActivateOptionResponse], error)
	EvaluateOption(context.Context, *connect.Request[v1.EvaluateOptionRequest]) (*connect.Response[v1.EvaluateOptionResponse], error)
	SelectOption(context.Context, *connect.Request[v1.SelectOptionRequest]) (*connect.Response[v1.SelectOptionResponse], error)
	RejectOption(context.Context, *connect.Request[v1.RejectOptionRequest]) (*connect.Response[v1.RejectOptionResponse], error)
	ListOptions(context.Context, *connect.Request[v1.ListOptionsRequest]) (*connect.Response[v1.ListOptionsResponse], error)
	CompareOptions(context.Context, *connect.Request[v1.CompareOptionsRequest]) (*connect.Response[v1.CompareOptionsResponse], error)
	// The graph a change sees at a level (written, accepted, landed) on a flow (ADR 0032 §5), and the graph a call on
	// the change reads (the active option's, else the reference baseline).
	GetChangeView(context.Context, *connect.Request[v1.GetChangeViewRequest]) (*connect.Response[v1.GetChangeViewResponse], error)
	// Decision points of a change (ADR 0009 §4): opened, ruled (decided or undecidable with questions), their questions
	// answered, an agent ruling below the threshold ratified by a person; a decided point selects its option.
	OpenDecision(context.Context, *connect.Request[v1.OpenDecisionRequest]) (*connect.Response[v1.OpenDecisionResponse], error)
	RuleDecision(context.Context, *connect.Request[v1.RuleDecisionRequest]) (*connect.Response[v1.RuleDecisionResponse], error)
	AnswerQuestion(context.Context, *connect.Request[v1.AnswerQuestionRequest]) (*connect.Response[v1.AnswerQuestionResponse], error)
	RatifyDecision(context.Context, *connect.Request[v1.RatifyDecisionRequest]) (*connect.Response[v1.RatifyDecisionResponse], error)
	ListDecisionPoints(context.Context, *connect.Request[v1.ListDecisionPointsRequest]) (*connect.Response[v1.ListDecisionPointsResponse], error)
	GetChangeGraph(context.Context, *connect.Request[v1.GetChangeGraphRequest]) (*connect.Response[v1.GetChangeGraphResponse], error)
	// The execution journal (ADR 0011, pkg/journal) is entries of the log of a change: appended with AppendLog, read as
	// records with ListExecutions (or as entries with ListChangeLog)
	AppendLog(context.Context, *connect.Request[v1.AppendLogRequest]) (*connect.Response[v1.AppendLogResponse], error)
	ListExecutions(context.Context, *connect.Request[v1.ListExecutionsRequest]) (*connect.Response[v1.ListExecutionsResponse], error)
	// Node index (ADR 0026): publishes again the event of every node version and the head of main, to
	// rebuild an index. Requires `admin` on the `platform` resource.
	RepublishIndex(context.Context, *connect.Request[v1.RepublishIndexRequest]) (*connect.Response[v1.RepublishIndexResponse], error)
}

